select.if:
SELECT T1.TOTLE_TRADE_ID busiCode, T1.P_TRADE_ID, T4.FINPROD_ID, T1.CCY, T4.BASIS, T4.INT_RATE, T1.COUNTER_ID, T8.COUNTER_NAME, T1.TRADER, PP.PORTFOLIO_ID, PP.PORTFOLIO_NAME, T6.FINPROD_ID pledgeFinprodId, /*标的金融产品代码*/ T6.FINPROD_NAME, /*标的金融产品名称*/ T3.BACK_LEND_DIRECTION ps, T4.VDATE, T4.MDATE, T1.MDATE-T1.VDATE ACT_AMT_DAYS, T1.FINPROD_TYPE2 , T1.TRADE_DATE, /*交易日期*/ T1.SHARE_AMT,/*交易份额*/ T4.INT_RATE*100 mYield,/*借贷费率*/ T4.M_INT_AMT mTradeAmt, /*借贷费用*/ T1.TRADE_AMT , /*实际结算金额*/ T4.TERM_TYPE, T4.TERM, /*借贷期限*/ T9.DELIVERY_TYPE, /*结算方式*/ T4.M_DELIVERY_TYPE, /*到期结算方式*/ T4.CONFLICT_SOLVE_WAY, /*争议解决方式*/ T4.CALENDAR_ID, /*交易日历*/ T1.F_TRADE_ID,/*银行间成交编号*/ T1.SEC_MANAGE_ACCT_ID, totalAdd.IS_CASHSET isCashPay, T1.PRIN_AMT, T1.INV_AIM, T1.TRADE_MARKET TRADE_MARKET, T1.SETTLE_DATE FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD totalAdd on t1.totle_trade_id = totalAdd.totle_trade_id LEFT JOIN TRD_PRODUCT_DEAL T9 ON T1.FINPROD_ID = T9.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL T3 ON T1.FINPROD_ID = T3.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_DEAL_TARGET T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN FIN_PRODUCT T6 ON T6.FINPROD_ID = T5.PLEDGE_FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T8 ON T1.COUNTER_ID = T8.COUNTER_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE PP.INVEST_YESORNO = 'Y'
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND T1.P_TRADE_ID = #{busiCode}

mapper.select:
SELECT B.CASH_ID, B.CASH_TYPE
FROM FIN_CASH_INFO A LEFT JOIN FIN_CASH_PLAN B ON A.CASH_ID = B.CASH_ID
WHERE A.FINPROD_ID= #{finprodId}

select A.PROD_REGIST_CODE
from FIN_PRODUCT_ADD A inner join FIN_PRODUCT B
             on A.FINPROD_ID = B.FINPROD_ID
             and B.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06}
WHERE B.FINPROD_MARKET_ID = #{portfolioId}

mapper.update:
UPDATE PTL_SEC_POSITION
SET AMOUNT = AMOUNT + #{amount}
WHERE BRANCH = #{branch}
       AND SEC_ACCT_ID = #{secAcctId}
       AND CDATE = #{cdate}
       AND HODING_TYPE = #{hodingType}
       AND PORTFOLIO_ID = #{portfolioId}
       AND FINPROD_ID = #{finprodId}

mapper.select:
select
    SUM(AMOUNT)
from ETR_SEC_POSITION_RULE
where CDATE = #{cdate,jdbcType=DATE} and date_type=0
  and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
  and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and CCY = #{ccy,jdbcType=VARCHAR}
